<?php

declare(strict_types=1);

use Illuminate\Cache\RedisStore;
use Illuminate\Filesystem\Filesystem;
use Illuminate\Http\Request;
use Illuminate\Support\Carbon;
use Illuminate\Support\Env;
use Illuminate\Support\Facades\Cache;
use Korioinc\ExpoIntegrity\Http\Middleware\ExpoIntegrityMiddleware;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\HttpKernel\Exception\HttpException;

/**
 * Independent fixtures generated by the Expo kit's Node signer, not PHP verifier logic.
 *
 * @return array<string, string>
 */
function expoIntegrityProof(): array
{
    return [
        'app-version' => '1.0.0',
        'x-integrity-timestamp' => '1800000000',
        'x-integrity-nonce' => '6b00e4a168f84d59a579561ef4015010',
        'x-integrity-signature' => '399891b96040affa2f63a4a9e06ffaae58e47b41bfe1eda1bfd3cab758b3f6e9',
    ];
}

/**
 * @param  array<string, string|array<int, string>>  $headers
 */
function expoIntegrityRequest(array $headers, string $method = 'POST', string $path = '/api/integrity-probe?value=%2F&value=2', string $body = '{"message":"안녕 👋"}'): Request
{
    $request = Request::create($path, $method, content: $body);
    $request->headers->replace($headers);

    return $request;
}

beforeEach(function (): void {
    $this->travelTo(Carbon::createFromTimestampUTC(1800000017));
    config()->set('laravel-expo-integrity.secret', '0820f4c898479b61647b690152fe9f4e9a3d764d199c8f0cab64c02924edabb8');
});

test('valid Expo proof authorizes the protected result and replay does not', function (): void {
    $values = [];
    $store = Mockery::mock(RedisStore::class);
    $store->shouldReceive('get')->andReturnUsing(function (string $key) use (&$values): mixed {
        return $values[$key] ?? null;
    });
    $store->shouldReceive('put')->andReturnUsing(function (string $key, mixed $value) use (&$values): bool {
        $values[$key] = $value;

        return true;
    });
    $store->shouldReceive('add')->andReturnUsing(function (string $key, mixed $value) use (&$values): bool {
        if (array_key_exists($key, $values)) {
            return false;
        }
        $values[$key] = $value;

        return true;
    });
    Cache::extend('integrity-test', fn () => Cache::repository($store));
    config()->set('cache.stores.integrity-test', ['driver' => 'integrity-test']);
    config()->set('laravel-expo-integrity.cache_store', 'integrity-test');
    $middleware = app(ExpoIntegrityMiddleware::class);
    $next = fn (Request $request): Response => new Response('protected-result');

    $result = $middleware->handle(expoIntegrityRequest(expoIntegrityProof()), $next);
    expect($result->getContent())->toBe('protected-result');
    expect(fn () => $middleware->handle(expoIntegrityRequest(expoIntegrityProof()), $next))->toThrow(HttpException::class);
});

test('a correctly signed app update is accepted without registering its version', function (): void {
    $headers = expoIntegrityProof();
    $headers['app-version'] = '2.0.0';
    $headers['x-integrity-signature'] = 'd47816a0b7c9d528c0c62a1e1abe240eedbb3d62fb4b3130bcb7d16f007b641d';
    $values = [];
    $store = Mockery::mock(RedisStore::class);
    $store->shouldReceive('get')->andReturnUsing(function (string $key) use (&$values): mixed {
        return $values[$key] ?? null;
    });
    $store->shouldReceive('put')->andReturnUsing(function (string $key, mixed $value) use (&$values): bool {
        $values[$key] = $value;

        return true;
    });
    $store->shouldReceive('add')->andReturn(true);
    Cache::extend('integrity-test', fn () => Cache::repository($store));
    config()->set('cache.stores.integrity-test', ['driver' => 'integrity-test']);
    config()->set('laravel-expo-integrity.cache_store', 'integrity-test');
    $next = fn (Request $request): Response => new Response('protected-result');

    $result = app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest($headers), $next);

    expect($result->getContent())->toBe('protected-result');
});

test('modified or malformed proof cannot authorize a protected result', function (string $change): void {
    $headers = expoIntegrityProof();
    $method = 'POST';
    $path = '/api/integrity-probe?value=%2F&value=2';
    $body = '{"message":"안녕 👋"}';
    match ($change) {
        'body' => $body = '{"message":"changed"}',
        'method' => $method = 'DELETE',
        'path' => $path = '/api/other?value=%2F&value=2',
        'query' => $path = '/api/integrity-probe?value=2&value=%2F',
        'version' => $headers['app-version'] = '2.0.0',
        'nonce' => $headers['x-integrity-nonce'] = str_repeat('f', 32),
        'signature' => $headers['x-integrity-signature'] = str_repeat('0', 64),
        'missing' => $headers = [],
        'duplicate' => $headers['app-version'] = ['1.0.0', '1.0.0'],
        'timestamp' => $headers['x-integrity-timestamp'] = '1800000017',
        'old' => $headers['x-integrity-timestamp'] = '1799999700',
        'future' => $headers['x-integrity-timestamp'] = '1800000300',
        'encoding' => $headers['Content-Encoding'] = 'gzip',
        'override' => $headers['X-HTTP-Method-Override'] = 'DELETE',
        'timestamp-leading-zero' => $headers['x-integrity-timestamp'] = '01800000000',
        'version-newline' => $headers['app-version'] = "1.0.0\n",
        'nonce-uppercase' => $headers['x-integrity-nonce'] = strtoupper($headers['x-integrity-nonce']),
        'signature-uppercase' => $headers['x-integrity-signature'] = strtoupper($headers['x-integrity-signature']),
    };
    $store = Mockery::mock(RedisStore::class);
    $store->shouldReceive('get')->andReturn(null);
    $store->shouldReceive('put')->andReturn(true);
    $store->shouldReceive('add')->andReturn(true);
    Cache::extend('integrity-test', fn () => Cache::repository($store));
    config()->set('cache.stores.integrity-test', ['driver' => 'integrity-test']);
    config()->set('laravel-expo-integrity.cache_store', 'integrity-test');
    $next = fn (Request $request): Response => new Response('protected-result');

    expect(fn () => app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest($headers, $method, $path, $body), $next))
        ->toThrow(HttpException::class);
})->with(['body', 'method', 'path', 'query', 'version', 'nonce', 'signature', 'missing', 'duplicate', 'timestamp', 'old', 'future', 'encoding', 'override', 'timestamp-leading-zero', 'version-newline', 'nonce-uppercase', 'signature-uppercase']);

test('an expired valid proof cannot authorize a protected result', function (): void {
    $this->travelTo(Carbon::createFromTimestampUTC(1800000120));
    $next = fn (Request $request): Response => new Response('protected-result');

    expect(fn () => app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest(expoIntegrityProof()), $next))
        ->toThrow(HttpException::class);
});

test('nonce storage failure cannot authorize a protected result', function (): void {
    $store = Mockery::mock(RedisStore::class);
    $store->shouldReceive('get')->andReturn(null);
    $store->shouldReceive('put')->andReturn(true);
    $store->shouldReceive('add')->andThrow(new RuntimeException('Nonce store unavailable'));
    Cache::extend('integrity-test', fn () => Cache::repository($store));
    config()->set('cache.stores.integrity-test', ['driver' => 'integrity-test']);
    config()->set('laravel-expo-integrity.cache_store', 'integrity-test');
    $next = fn (Request $request): Response => new Response('protected-result');

    expect(fn () => app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest(expoIntegrityProof()), $next))
        ->toThrow(HttpException::class);
});

test('file-backed proof authorizes once across separate cache instances', function (): void {
    $directory = sys_get_temp_dir().DIRECTORY_SEPARATOR.'expo-integrity-'.bin2hex(random_bytes(16));
    config()->set('cache.stores.integrity-file-test', ['driver' => 'file', 'path' => $directory]);
    config()->set('laravel-expo-integrity.cache_store', 'integrity-file-test');
    $next = fn (Request $request): Response => new Response('protected-result');

    try {
        $result = app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest(expoIntegrityProof()), $next);
        expect($result->getContent())->toBe('protected-result');
        app('cache')->forgetDriver('integrity-file-test');
        expect(fn () => app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest(expoIntegrityProof()), $next))
            ->toThrow(HttpException::class);
    } finally {
        app('cache')->forgetDriver('integrity-file-test');
        (new Filesystem)->deleteDirectory($directory);
    }
});

test('string keys authorize only an unchanged request and cannot be replayed', function (string $secret, string $signature): void {
    $repository = Env::getRepository();
    $originalSecret = $repository->get('INTEGRITY_SECRET');
    $repository->clear('INTEGRITY_SECRET');
    $repository->set('INTEGRITY_SECRET', $secret);

    try {
        $configuration = require __DIR__.'/../../config/laravel-expo-integrity.php';
        config()->set('laravel-expo-integrity.secret', $configuration['secret']);
    } finally {
        $repository->clear('INTEGRITY_SECRET');

        if ($originalSecret !== null) {
            $repository->set('INTEGRITY_SECRET', $originalSecret);
        }
    }
    $directory = sys_get_temp_dir().DIRECTORY_SEPARATOR.'expo-integrity-string-'.bin2hex(random_bytes(16));
    config()->set('cache.stores.integrity-string-test', ['driver' => 'file', 'path' => $directory]);
    config()->set('laravel-expo-integrity.cache_store', 'integrity-string-test');
    $headers = expoIntegrityProof();
    $headers['x-integrity-signature'] = $signature;
    $next = fn (Request $request): Response => new Response('protected-result');

    try {
        expect(fn () => app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest($headers, body: 'changed'), $next))
            ->toThrow(HttpException::class);
        $result = app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest($headers), $next);
        expect($result->getContent())->toBe('protected-result');
        expect(fn () => app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest($headers), $next))
            ->toThrow(HttpException::class);
    } finally {
        app('cache')->forgetDriver('integrity-string-test');
        (new Filesystem)->deleteDirectory($directory);
    }
})->with([
    'short' => ['x', 'ab72bfbab3909c27ba029bd86c4a3821ff63e8b5f2e2844e1ebffe6dd09b520d'],
    'UUID' => ['cd20d4fc-e14c-4804-97bd-34280c68d69b', '6c19a49de883a0e631ef3cfcd78355b9e380700e2699952677cf81203f95b133'],
    'Unicode' => ['공유 키 🔑', 'de5cdae78fdf2be93d2a598609afa4be8ea11db53aefbd46105b3fb937548980'],
    'whitespace' => ['   ', 'ae9d10757f0d5d3bfee524524addec7dba542a4903e1e8728aaa5c27145af9ac'],
    'long' => [str_repeat('key', 100), '9dcea88464075198a8b887872ff0204478d1d17f4cd819f30bc9db02a09881ee'],
    'literal true' => ['true', '764016cb14603eca1dabd485a3d3a81c47860cab0a1e7a9d94427acffe6ff0be'],
    'literal false' => ['false', '647ddda5e540b49f574be6824d9be752849464cb76f7f91e4c48cfa4a15b896e'],
    'literal null' => ['null', '3529c7b8a46bd3cd3b449b492689a921e83e33b4593213c57913c9e471ab8e93'],
    'literal empty' => ['empty', '9010c9eb9834a84c3b15e99fdd6556e1a9acb50ea2ec9cbd89b574fab6f2d482'],
    'literal parenthesized true' => ['(true)', 'd297746cb2d6af6cbfeef1566afe71f4669c9c5cee36bc878e68b81931d23a57'],
    'zero' => ['0', '2e3564e5c81f9c1d7387ccc91a8c24a2e4b6e9dc2f8b4177109c6f2c1b79d622'],
]);

test('a process-local replay cache cannot authorize a protected result', function (): void {
    config()->set('laravel-expo-integrity.cache_store', 'array');
    $next = fn (Request $request): Response => new Response('protected-result');

    expect(fn () => app(ExpoIntegrityMiddleware::class)->handle(expoIntegrityRequest(expoIntegrityProof()), $next))
        ->toThrow(HttpException::class);
});
